window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-85a53aaedbbe16ae"]={"versions": [{"id": "FIG-85a53aaedbbe16ae", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Serialisierungs-Layout im Bit-/Byte-Ebenen-Kontext des SOME/IP-Protokolls (AUTOSAR Classic & Adaptive Platform). Das Diagramm spezifiziert die Serialisierung und das Speicherabbild eines eindimensionalen Arrays fester Länge (<code>Static Array a[n]</code>) innerhalb einer SOME/IP-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array a[n]</code>: Gesamter Datencontainer des statischen Arrays.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, <code>Element_n</code>: Sequenziell aufeinanderfolgende Array-Elemente (Kardinalität <code>n</code>).</li>\n<li><code>element size e</code>: Feste Bytegröße bzw. Datenlänge eines einzelnen Elements.</li>\n<li><code>n * e</code>: Gesamtlänge des serialisierten Arrays im Datenstrom, berechnet aus Anzahl <code>n</code> mal Elementgröße <code>e</code>.</li>\n<li>Auslassungszeichen (<code>...</code>): Symbolisiert die fortlaufende Sequenz zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsabfolge: Die Elemente des Arrays werden ohne vorangestelltes Längenfeld direkt hintereinander in nativer Reihenfolge von Index 1 bis <code>n</code> in die SOME/IP-Nachricht serialisiert bzw. aus ihr deserialisiert. Jedes Element belegt exakt die Elementgröße <code>e</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des Payloads für statische Arrays mit fester Elementanzahl:</p>\n<ul class=\"fig-list\">\n<li>Das Array besitzt kein Längenfeld; die Gesamtlänge ist fest über <code>n * e</code> bestimmt.</li>\n<li>Alle Elemente besitzen dieselbe statische Größe <code>e</code>.</li>\n<li>Sender und Empfänger müssen die Dimension <code>n</code> und Elementgröße <code>e</code> a priori über die Schnittstellenkonfiguration kennen.</li>\n</ul>"}, {"id": "FIG-07335cd7f0043330", "releases": ["R1.5.1", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Serialisierungs-Layout im Bit-/Byte-Ebenen-Kontext des SOME/IP-Protokolls (AUTOSAR Classic & Adaptive Platform). Das Diagramm spezifiziert die Serialisierung und das Speicherabbild eines eindimensionalen Arrays fester Länge (<code>Static Array a[n]</code>) innerhalb einer SOME/IP-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array a[n]</code>: Gesamter Datencontainer des statischen Arrays.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, <code>Element_n</code>: Sequenziell aufeinanderfolgende Array-Elemente (Kardinalität <code>n</code>).</li>\n<li><code>element size e</code>: Feste Bytegröße bzw. Datenlänge eines einzelnen Elements.</li>\n<li><code>n * e</code>: Gesamtlänge des serialisierten Arrays im Datenstrom, berechnet aus Anzahl <code>n</code> mal Elementgröße <code>e</code>.</li>\n<li>Auslassungszeichen (<code>...</code>): Symbolisiert die fortlaufende Sequenz zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsabfolge: Die Elemente des Arrays werden ohne vorangestelltes Längenfeld direkt hintereinander in nativer Reihenfolge von Index 1 bis <code>n</code> in die SOME/IP-Nachricht serialisiert bzw. aus ihr deserialisiert. Jedes Element belegt exakt die Elementgröße <code>e</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des Payloads für statische Arrays mit fester Elementanzahl:</p>\n<ul class=\"fig-list\">\n<li>Das Array besitzt kein Längenfeld; die Gesamtlänge ist fest über <code>n * e</code> bestimmt.</li>\n<li>Alle Elemente besitzen dieselbe statische Größe <code>e</code>.</li>\n<li>Sender und Empfänger müssen die Dimension <code>n</code> und Elementgröße <code>e</code> a priori über die Schnittstellenkonfiguration kennen.</li>\n</ul>"}, {"id": "FIG-2bfbec7ce139c07e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Serialisierungs-Layout im Bit-/Byte-Ebenen-Kontext des SOME/IP-Protokolls (AUTOSAR Classic & Adaptive Platform). Das Diagramm spezifiziert die Serialisierung und das Speicherabbild eines eindimensionalen Arrays fester Länge (<code>Static Array a[n]</code>) innerhalb einer SOME/IP-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array a[n]</code>: Gesamter Datencontainer des statischen Arrays.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, <code>Element_n</code>: Sequenziell aufeinanderfolgende Array-Elemente (Kardinalität <code>n</code>).</li>\n<li><code>element size e</code>: Feste Bytegröße bzw. Datenlänge eines einzelnen Elements.</li>\n<li><code>n * e</code>: Gesamtlänge des serialisierten Arrays im Datenstrom, berechnet aus Anzahl <code>n</code> mal Elementgröße <code>e</code>.</li>\n<li>Auslassungszeichen (<code>...</code>): Symbolisiert die fortlaufende Sequenz zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsabfolge: Die Elemente des Arrays werden ohne vorangestelltes Längenfeld direkt hintereinander in nativer Reihenfolge von Index 1 bis <code>n</code> in die SOME/IP-Nachricht serialisiert bzw. aus ihr deserialisiert. Jedes Element belegt exakt die Elementgröße <code>e</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des Payloads für statische Arrays mit fester Elementanzahl:</p>\n<ul class=\"fig-list\">\n<li>Das Array besitzt kein Längenfeld; die Gesamtlänge ist fest über <code>n * e</code> bestimmt.</li>\n<li>Alle Elemente besitzen dieselbe statische Größe <code>e</code>.</li>\n<li>Sender und Empfänger müssen die Dimension <code>n</code> und Elementgröße <code>e</code> a priori über die Schnittstellenkonfiguration kennen.</li>\n</ul>"}, {"id": "FIG-7c0e56a9a52688bf", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Serialisierungs-Layout im Bit-/Byte-Ebenen-Kontext des SOME/IP-Protokolls (AUTOSAR Classic & Adaptive Platform). Das Diagramm spezifiziert die Serialisierung und das Speicherabbild eines eindimensionalen Arrays fester Länge (<code>Static Array [n]</code>) mit Unterstützung eines optionalen Längenfelds innerhalb einer SOME/IP-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array [n]</code>: Gesamter Datencontainer des statischen Arrays.</li>\n<li><code>LengthField (optional)</code>: Dem Datenstrom der Elemente optional vorangestelltes Längenfeld.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, <code>Element_n</code>: Sequenziell aufeinanderfolgende Array-Elemente (Kardinalität <code>n</code>).</li>\n<li><code>element size e</code>: Feste Bytegröße bzw. Datenlänge eines einzelnen Elements.</li>\n<li><code>n*e</code>: Gesamtlänge des Nutzdatenbereichs der sequenziellen Array-Elemente.</li>\n<li><code>LengthField + n*e</code>: Gesamtlänge des serialisierten Datenblocks inklusive des optionalen Längenfelds.</li>\n<li>Auslassungszeichen (<code>...</code>): Symbolisiert die fortlaufende Sequenz zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsabfolge:</p>\n<ol class=\"fig-list\">\n<li>Sofern konfiguriert, wird zuerst das <code>LengthField</code> übertragen, welches die Bytegröße der nachfolgenden Nutzdaten (<code>n*e</code>) angibt.</li>\n<li>Direkt anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell übertragen.</li>\n<li>Jedes Element belegt die konfigurierte Bytegröße <code>e</code>. Entfällt das optionale Längenfeld, beginnt die Serialisierung unmittelbar mit <code>Element_1</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des Payloads für statische Arrays mit fester Elementanzahl:</p>\n<ul class=\"fig-list\">\n<li>Die Spezifikation erlaubt ein optionales <code>LengthField</code> vor den Array-Elementen.</li>\n<li>Die Nutzdatenlänge ist das Produkt aus Elementanzahl und Elementgröße (<code>n*e</code>).</li>\n<li>Die Gesamtgröße des übertragenen Containers beträgt <code>LengthField + n<em>e</code> (sofern das Längenfeld konfiguriert ist) bzw. <code>n</em>e</code> (ohne Längenfeld).</li>\n<li>Die Konfiguration des Längenfelds (Vorhandensein und Bytegröße) sowie <code>n</code> und <code>e</code> müssen in der Schnittstellenbeschreibung übereinstimmend parametriert sein.</li>\n</ul>"}, {"id": "FIG-fc8dfcf6bb4d4e8c", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Serialisierungs-Layout im Bit-/Byte-Ebenen-Kontext des SOME/IP-Protokolls (AUTOSAR Classic & Adaptive Platform). Das Diagramm spezifiziert die Serialisierung und das Speicherabbild eines eindimensionalen Arrays fester Länge (<code>Static Array [n]</code>) mit Unterstützung eines optionalen Längenfelds innerhalb einer SOME/IP-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array [n]</code>: Gesamter Datencontainer des statischen Arrays.</li>\n<li><code>LengthField (optional)</code>: Dem Datenstrom der Elemente optional vorangestelltes Längenfeld.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, <code>Element_n</code>: Sequenziell aufeinanderfolgende Array-Elemente (Kardinalität <code>n</code>).</li>\n<li><code>element size e</code>: Feste Bytegröße bzw. Datenlänge eines einzelnen Elements.</li>\n<li><code>n*e</code>: Gesamtlänge des Nutzdatenbereichs der sequenziellen Array-Elemente.</li>\n<li><code>LengthField + n*e</code>: Gesamtlänge des serialisierten Datenblocks inklusive des optionalen Längenfelds.</li>\n<li>Auslassungszeichen (<code>...</code>): Symbolisiert die fortlaufende Sequenz zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsabfolge:</p>\n<ol class=\"fig-list\">\n<li>Sofern konfiguriert, wird zuerst das <code>LengthField</code> übertragen, welches die Bytegröße der nachfolgenden Nutzdaten (<code>n*e</code>) angibt.</li>\n<li>Direkt anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell übertragen.</li>\n<li>Jedes Element belegt die konfigurierte Bytegröße <code>e</code>. Entfällt das optionale Längenfeld, beginnt die Serialisierung unmittelbar mit <code>Element_1</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des Payloads für statische Arrays mit fester Elementanzahl:</p>\n<ul class=\"fig-list\">\n<li>Die Spezifikation erlaubt ein optionales <code>LengthField</code> vor den Array-Elementen.</li>\n<li>Die Nutzdatenlänge ist das Produkt aus Elementanzahl und Elementgröße (<code>n*e</code>).</li>\n<li>Die Gesamtgröße des übertragenen Containers beträgt <code>LengthField + n<em>e</code> (sofern das Längenfeld konfiguriert ist) bzw. <code>n</em>e</code> (ohne Längenfeld).</li>\n<li>Die Konfiguration des Längenfelds (Vorhandensein und Bytegröße) sowie <code>n</code> und <code>e</code> müssen in der Schnittstellenbeschreibung übereinstimmend parametriert sein.</li>\n</ul>"}, {"id": "FIG-e5e46702edb46a70", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Serialisierungs-Layout im Bit-/Byte-Ebenen-Kontext des SOME/IP-Protokolls (AUTOSAR Classic & Adaptive Platform). Das Diagramm spezifiziert die Serialisierung und das Speicherabbild eines eindimensionalen Arrays fester Länge (<code>Static Array [n]</code>) mit Unterstützung eines optionalen Längenfelds innerhalb einer SOME/IP-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array [n]</code>: Gesamter Datencontainer des statischen Arrays.</li>\n<li><code>LengthField (optional)</code>: Dem Datenstrom der Elemente optional vorangestelltes Längenfeld.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, <code>Element_n</code>: Sequenziell aufeinanderfolgende Array-Elemente (Kardinalität <code>n</code>).</li>\n<li><code>element size e</code>: Feste Bytegröße bzw. Datenlänge eines einzelnen Elements.</li>\n<li><code>n*e</code>: Gesamtlänge des Nutzdatenbereichs der sequenziellen Array-Elemente.</li>\n<li><code>LengthField + n*e</code>: Gesamtlänge des serialisierten Datenblocks inklusive des optionalen Längenfelds.</li>\n<li>Auslassungszeichen (<code>...</code>): Symbolisiert die fortlaufende Sequenz zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsabfolge:</p>\n<ol class=\"fig-list\">\n<li>Sofern konfiguriert, wird zuerst das <code>LengthField</code> übertragen, welches die Bytegröße der nachfolgenden Nutzdaten (<code>n*e</code>) angibt.</li>\n<li>Direkt anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell übertragen.</li>\n<li>Jedes Element belegt die konfigurierte Bytegröße <code>e</code>. Entfällt das optionale Längenfeld, beginnt die Serialisierung unmittelbar mit <code>Element_1</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des Payloads für statische Arrays mit fester Elementanzahl:</p>\n<ul class=\"fig-list\">\n<li>Die Spezifikation erlaubt ein optionales <code>LengthField</code> vor den Array-Elementen.</li>\n<li>Die Nutzdatenlänge ist das Produkt aus Elementanzahl und Elementgröße (<code>n*e</code>).</li>\n<li>Die Gesamtgröße des übertragenen Containers beträgt <code>LengthField + n<em>e</code> (sofern das Längenfeld konfiguriert ist) bzw. <code>n</em>e</code> (ohne Längenfeld).</li>\n<li>Die Konfiguration des Längenfelds (Vorhandensein und Bytegröße) sowie <code>n</code> und <code>e</code> müssen in der Schnittstellenbeschreibung übereinstimmend parametriert sein.</li>\n</ul>"}], "trans": [{"from": "FIG-85a53aaedbbe16ae", "to": "FIG-07335cd7f0043330", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-07335cd7f0043330", "to": "FIG-85a53aaedbbe16ae", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-07335cd7f0043330", "to": "FIG-2bfbec7ce139c07e", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2bfbec7ce139c07e", "to": "FIG-7c0e56a9a52688bf", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Datenstruktur: Voranstellung eines optionalen Längenfelds (<code>LengthField (optional)</code>) vor dem ersten Array-Element.</li>\n<li>Maßangaben: Ergänzung einer Gesamtlängenbemaßung über das gesamte Array inklusive Längenfeld (<code>LengthField + n<em>e</code>) sowie Verschiebung der Bemaßung <code>n</em>e</code> auf den reinen Nutzdatenbereich der Elemente.</li>\n<li>Beschriftung: Array-Bezeichnung von <code>Static Array a[n]</code> in <code>Static Array [n]</code> geändert; Multiplikationsschreibweise von <code>n <em> e</code> zu <code>n</em>e</code> verdichtet.</li>\n</ul>"}, {"from": "FIG-7c0e56a9a52688bf", "to": "FIG-fc8dfcf6bb4d4e8c", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fc8dfcf6bb4d4e8c", "to": "FIG-e5e46702edb46a70", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
